  BUILD('Spell the word','Listen. Build the word.',['c|a|p','b|a|g','b|i|k|e','sh|oe|s','w|a|tch','j|a|ck|e|t','gl|a|ss|e|s','sh|i|r|t','j|ea|n|s','sk|ir|t','h|oo|d|ie','b|oo|t|s']),
  SPEED('Speed game',['cap','bag','bike','shoes','watch','jacket','glasses','jeans','skirt','trainers','hoodie','laptop']),
  SPEAK('What\'s in your bag?','Look at the photo. Say it.',['Point to the cap. What colour is it?','Show me your bag. Say: This is my …','Say: These are my …','Ask your teacher: Is this your …?','Name 5 things you have got.'],["This is my …","These are my …","It's red / blue / yellow.","Is this your …?","Yes, it is. / No, it isn't."],40,['gf2-cap','gf2-bag','gf2-shoes','gf2-jacket','gf2-watch'])
